"""Individually authored 64px fighters, plus a native96 ogre.
Every torso, bent leg, hand, costume and fallen body is explicit final-grid art.
"""
from humanoid import P,BASE

def pal(**r):a=BASE.copy();a.update(r);return a
GREEN=pal(d='283e41',s='416550',m='669363',g='9abd7c',h='c7d99b')
RED=pal(d='49353d',s='705049',m='9b735c',g='c49b79',h='e5c399')

def goblin_head(p,x,y,brute=False):
 p.at('head')
 p.poly([(x+3,y+1),(x+10,y),(x+15,y+4),(x+14,y+8),(x+18,y+10),(x+17,y+14),(x+11,y+17),(x+4,y+16),(x+1,y+12),(x,y+7)],'s','o')
 p.poly([(x+3,y+3),(x+8,y+2),(x+11,y+4),(x+9,y+7),(x+3,y+8),(x+1,y+6)],'g')
 p.poly([(x+1,y+5),(x-7,y+1),(x-4,y+9),(x+2,y+11)],'m','o');p.line([(x-4,y+4),(x,y+7)],'g')
 p.poly([(x+10,y+8),(x+17,y+8),(x+20,y+10),(x+19,y+12),(x+12,y+12),(x+9,y+10)],'m','o');p.line([(x+13,y+9),(x+17,y+9)],'h');p.dot(x+18,y+10,'d')
 p.poly([(x+4,y+9),(x+8,y+8),(x+10,y+11),(x+8,y+14),(x+4,y+13)],'m');p.line([(x+4,y+10),(x+6,y+10)],'g')
 p.line([(x+9,y+14),(x+16,y+14)],'z');p.dots(x+12,y+13,['w.w','.w.']);p.eye(x+11,y+6)
 p.line([(x+8,y+4),(x+12,y+4),(x+15,y+5)],'d',2)
 if brute:
  p.poly([(x+12,y+15),(x+13,y+10),(x+15,y+12),(x+15,y+16)],'Y','o');p.dot(x+13,y+12,'w');p.line([(x+3,y+10),(x+4,y+13)],'R');p.dot(x+4,y+11,'P')
  p.poly([(x+1,y+2),(x,y-2),(x+5,y-4),(x+10,y-2),(x+13,y+1),(x+8,y+1)],'d');p.line([(x+3,y-1),(x+7,y-2)],'m')
 else:
  p.poly([(x+1,y+2),(x+2,y-2),(x+9,y-3),(x+12,y),(x+7,y+1)],'b','o');p.line([(x+4,y-1),(x+8,y-1)],'T')

