def orc_head(p,x,y,shaman=False):
 p.at('head');p.poly([(x+3,y),(x+11,y),(x+16,y+4),(x+15,y+9),(x+19,y+11),(x+18,y+17),(x+12,y+19),(x+4,y+18),(x,y+13),(x-1,y+6)],'s','o')
