 for xx in (x+12,x+18):p.poly([(xx,y+17),(xx-1,y+11),(xx+1,y+10),(xx+3,y+15),(xx+2,y+18)],'Y','o');p.line([(xx,y+12),(xx+1,y+15)],'w')
 p.eye(x+12,y+6);p.line([(x+8,y+4),(x+13,y+4),(x+16,y+5)],'d',2)
 if shaman:p.line([(x+5,y+11),(x+10,y+13)],'p');p.dot(x+8,y+12,'P')
 else:
  p.poly([(x+2,y),(x+1,y-3),(x+6,y-5),(x+10,y-3),(x+12,y),(x+6,y-1)],'d');p.line([(x+3,y-2),(x+7,y-3)],'m')

